def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj):
        if isinstance(obj, dict):
            return obj.get("x", 0), obj.get("y", 0)
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return 0, 0

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = observation.get("self_position", observation.get("position", (0, 0)))
    ox, oy = observation.get("opponent_position", observation.get("enemy_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    gw = observation.get("grid_width", 0) or observation.get("width", 0) or 0
    gh = observation.get("grid_height", 0) or observation.get("height", 0) or 0
    center = (gw // 2, gh // 2) if gw and gh else self_pos

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        corners = [c for c in corners if c[0] >= 0 and c[1] >= 0]
        if corners:
            target = max(corners, key=lambda c: manhattan(c, opp_pos))
            return step_toward(self_pos, target)
        return step_toward(self_pos, center)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        if targets:
            best = min(targets, key=lambda item: manhattan(self_pos, pos(item)))
            return step_toward(self_pos, pos(best))
        if gw and gh:
            return step_toward(self_pos, center)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = min(resources, key=lambda item: manhattan(self_pos, pos(item)))
        return step_toward(self_pos, pos(best))

    # Fallbacks: move toward opponent if closer, otherwise drift to center.
    if gw and gh:
        if manhattan(self_pos, opp_pos) > manhattan(self_pos, center):
            return step_toward(self_pos, center)
    return step_toward(self_pos, opp_pos)

